import sys
from pathlib import Path

import yaml

from critisizer.db import SessionLocal
from critisizer.reviewed_data import export_reviewed

DEFAULT_FILE = Path("seed/reviewed.yaml")
HEADER = (
    "# Generated by scripts/export_reviewed.py from the local database.\n"
    "# Do not edit by hand; review in the admin API, then export again.\n"
)


def main(path: Path = DEFAULT_FILE) -> None:
    with SessionLocal() as session:
        data = export_reviewed(session)
    body = yaml.safe_dump(data, sort_keys=False, allow_unicode=True, width=100)
    path.write_text(HEADER + body, encoding="utf-8", newline="\n")
    print(f"wrote {path}")
    for item in data["policies"]:
        evidence = sum(len(i["evidence"]) for i in item["indicators"])
        print(
            f"{item['slug']:32} indicators={len(item['indicators'])} "
            f"evidence={evidence} reviews={len(item['aspect_reviews'])} "
            f"aims={len(item['aims'])} sources={len(item['source_items'])}"
        )


if __name__ == "__main__":
    main(Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_FILE)